export type IconName = "activity" | "add" | "alert-circle" | "alt-arrow-down" | "alt-arrow-right" | "arrow-left" | "arrow-right" | "arrow-right-up" | "arrow-up" | "arrow-up-right" | "bell" | "calendar" | "chart" | "chart-bar" | "chart-line" | "chat-round" | "chat-round-line" | "chat-square-line" | "check" | "check-circle" | "chevron-down" | "chevron-right" | "chevrons-up-down" | "circle-help" | "clock" | "clock-circle" | "close" | "copy" | "danger-circle" | "database" | "diagram-up" | "download" | "edit" | "expand" | "eye" | "file" | "filter" | "full-screen" | "globe" | "grid-2x2" | "hamburger-menu" | "history" | "info" | "info-circle" | "key" | "layers" | "layers-minimalistic" | "layout-dashboard" | "letter" | "list" | "lock" | "lock-unlocked" | "log-out" | "logout" | "magnifier" | "mail" | "maximize" | "menu" | "message-circle" | "message-square" | "messages" | "minus" | "network" | "panel-right" | "pen" | "play" | "plus" | "pulse" | "question-circle" | "refresh" | "reply" | "rocket" | "scale" | "search" | "send" | "send-square" | "settings" | "shield" | "snowflake" | "sparkles" | "stars-minimalistic" | "structure" | "table" | "target" | "trash" | "trash-bin-trash" | "undo-left-round" | "unlock" | "upload" | "user" | "user-plus" | "users" | "users-group-rounded" | "x";

/** One Solar outline icon. Static markup from the icon set; safe to inline. */
export function Icon({ name, size = 20, className, label }: { name: IconName | (string & {}); size?: number; className?: string; label?: string }) {
  const key = ALIASES[name] ?? name;
  const glyph = PATHS[key] ? key : "info-circle";
  return (
    <svg
      className={className ? `shrink-0 ${className}` : "shrink-0"}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      dangerouslySetInnerHTML={{ __html: PATHS[glyph] }}
    />
  );
}
